"""Summarize the source-backed converter audit and explicit manual rework list."""

from collections import Counter
import json
from pathlib import Path

PROJECT = Path(__file__).resolve().parent


def generate():
    reports = PROJECT / "reports"
    current = json.loads((reports / "converter-mechanism-audit.json").read_text(encoding="utf-8"))["results"][0]
    before = json.loads((reports / "converter-motion-before.json").read_text(encoding="utf-8"))["results"][0]
    old_times = {(r["sector"],r["kind"]):r for r in before["timings"]}
    gaps = [r for r in current["coverage"] if not r["lowered"]]
    corpus = json.loads((PROJECT.parents[1] / "reports/duke-motion-compatibility.json").read_text())
    lines = ["# Converter mechanism audit: E4L1", "",
             "Generated by `audit_report.py` from source/native audit JSON. This distinguishes converter bugs from manual remake decisions.", "",
             f"Source SHA-256: `{current['source_sha256']}`. Native remake SHA-256: `{current['converted_sha256']}`.", "",
             "## Reproduced and repaired bugs", "",
             "- SE11 first-operation direction was reversed: ST23 negates the spawn direction before moving. Door 50 dragged sector 389 loop 3 into a self-intersection at 8 of 16 sampled travel positions; the corrected swing has none. The earlier bathroom label for room 389 was wrong.",
             "- The actual bathroom is room 152 with stalls 58/59 and door 61. Its stray SE11 sprite 487 has hitag 409, with no same-hitag ST23 operator. The converter invented a Push rotor, then attached the room entry signal to it. Pass 09 restores a static room, preserves entry TX/command and retires marker 7 without renumbering. Door 61, hitag 408, remains a mover. E1L2 room 262 had the same inert-controller bug.",
             "- SE15 similarly adds 1024 to its authored angle before the first translation; the converter now uses that direction.",
             "- Tagged Z doors used fixed times or a fitted GPSPEED curve without distance. They now use endpoint distance and Duke's extra*4 step at 30 Hz. SE31/32 use sector extra copied into sprite.yvel, not sprite shade. Linear Blood wave 1 replaces default cosine easing.",
             "- Independent SE12 lighting overwrote mover controls in sectors 50, 61, 211 and 369 and the entry command in static room 152. Existing controls win; omitted independent lighting is diagnosed for manual treatment.",
             "- SE10 hitag is a 30 Hz counter, not Blood tenths. Return timing is put on the open end of the motion, including the OFF end of state-1 rotations. Presence holds and precise in-flight timer phase remain approximations.",
             "- SE20 marked slides moved a third vertex because both selected walls were flagged. Blood automatically carries point2, so only their connecting edge is now flagged. All 36 local-corpus stretch cases now agree with source geometry.",
             "- ST30 rising rotations had their Z endpoints reversed for state-1 initialization; their angle also now respects the engine's integer shift. Independent floor/rotation durations remain explicitly approximate when unequal.",
             "- SE13 expansion speed follows its source Z step, and source effector Z is preserved. Conflicting independent horizontal and explosive motion is diagnosed instead of replacing a rotation with Z-only motion.", "",
             "## What was verified", "",
             f"The historical pre-repair audit reported {before['moving_sectors']} failing horizontal comparisons; one of those controllers is now recognized as inert. The repaired map's active motions pass {current['ok']}/{current['moving_sectors']}, with maximum deviation {current['worst_deviation']} Blood units. Checks include affected neighbour loops and source-inherited folds; E4L1 also had the intrusion comparison enabled.", "",
             "Pass 08 is a guarded native patch. It changes motor extensions and 13 marker angles, adds no records, and preserves saved geometry, start, materials, weather and the declared briefing circuit. Backups preserve manual work.", "",
             "| Sector | Mechanism | Duke travel seconds | Before Blood seconds | After Blood seconds |",
             "| --- | --- | --- | --- | --- |"]
    for row in current["timings"]:
        if row["sector"] not in {8,73,108,115,391,520,50,369}:
            continue
        old = old_times.get((row["sector"],row["kind"]))
        lines.append(f"| {row['sector']} | {row['kind']} | {row['duke_ticks']/30:.3f} | "
                     f"{old['blood_completion_ticks']/30:.3f}" if old else f"| {row['sector']} | {row['kind']} | {row['duke_ticks']/30:.3f} | unknown")
        lines[-1] += f" | {row['blood_completion_ticks']/30:.3f} |"
    lines += ["", "Blood times include integer AddBusy increments and four-tic processing. Native tenths and tick quantization prevent exact timing; these are calculated motor completion times, not runtime recordings.", "",
              "## Manual rework and deliberate approximations", "",
              "The owner accepts manual reworking where direct translation is unsuitable. These limitations are not reasons to fabricate endpoints or abort the map. Full source fields and controller IDs remain in `converter-mechanism-audit.json`.", "",
              "| Item | Where | Treatment |", "| --- | --- | --- |",
              "| Compound ST26 doorway | sector 329 | Redesign as a native Blood doorway; combined ST9 vertex slide and ST22 Z split is not lowered. |",
              "| Pistons | sectors 504 and 514; SE sprites 50 and 31 | Decide native cycling machinery versus scenery from their role. |",
              "| Linked door leaves | sectors 15/16 and 327/328 | Shared operation is incomplete; review and wire the whole assembly together. |",
              "| Locked activators | sectors 8, 93, 97, 166, 362, 410 | Review lock/unlock sequencing and access controls. |",
              "| SE12 control conflicts | movers 50, 61, 211, 369; static entry-trigger room 152 | Keep repaired motion/entry controls; author independent light behavior deliberately. Other SE12 lowering remains a pulse approximation. |",
              "| Tape-player Use wall | wall 2318 | Generic converter still does not lower tagged wall Use; this remake already has an explicit three-wire briefing repair. |",
              "| Secret accounting | sectors 116, 221, 232, 270, 274, 388, 414 | Add native secret triggers during room work. |",
              "| Mirror / camera sets | mirror support 57, walls 277/570; scenery 535-542 | Keep mirror support distinct from rooms; camera-only sets remain disposable as approved. |",
              "| Audio, spawning, MasterSwitch choreography | see controller rows below and full JSON | Manual review; briefing speech remains unresolved. Sector 453's 10331 tag is enter sound 331, not a timed exit. |",
              "| Transport, conveyors, lighting | existing lowering records | Direction and structure do not prove activation, carrying physics, balance or exact light response. |", "",
              "Unsupported/incomplete inventory counts: " + ", ".join(f"{kind}: {count}" for kind,count in sorted(Counter(r["kind"] for r in gaps).items())) + ".", "",
              f"The available Duke corpus report is `reports/duke-motion-compatibility.json` at repository root: {corpus['maps']} maps, {corpus['moving_sectors']} horizontal movers, {corpus['problems']} modeled discrepancies, {len(corpus['conversion_failures'])} conversion failures. Two inert controllers are intentionally static. It checks modeled motion and conversion/read-back, not every map's finishability. No game windows or injected input were used. Runtime Use, obstruction/reversal, damage, audio and owner play remain unverified.", ""]
    (reports / "converter-mechanism-audit.md").write_text("\n".join(lines),encoding="utf-8")


if __name__ == "__main__":
    generate()
